code3='''from functools import lru_cache

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    n = len(markers)

    @lru_cache(None)
    def pair(mask):
        if mask == (1 << n) - 1:
            return (0, 0, ())
        i = next(i for i in range(n) if not (mask >> i) & 1)
        best = pair(mask | (1 << i))
        r, c = markers[i]
        for j in range(i + 1, n):
            if (mask >> j) & 1:
                continue
            rr, cc = markers[j]
            if r != rr and c != cc:
                continue
            count, distance, pairs = pair(mask | (1 << i) | (1 << j))
            candidate = (count + 1, distance + abs(r - rr) + abs(c - cc), ((i, j),) + pairs)
            if candidate[:2] > best[:2]:
                best = candidate
        return best

    _, _, pairs = pair(0)
    lines = set()
    for i, j in pairs:
        r, c = markers[i]
        rr, cc = markers[j]
        if r == rr:
            lines.update((r, x) for x in range(min(c, cc), max(c, cc) + 1))
        else:
            lines.update((x, c) for x in range(min(r, rr), max(r, rr) + 1))

    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                rr, cc = stack.pop()
                component.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2 and (nr,nc) not in seen:
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            if any(cell in lines for cell in component):
                for rr, cc in component:
                    out[rr][cc] = 1
    for r, c in lines:
        out[r][c] = 1
    return out
'''
